	L.RB_GM_ARTISANRY_SHOWS = "O badge da Associação dos Artesãos no retrato e ao lado do nome."
	L.RB_GM_ARTISANRY_UNLOCKS = "Um atalho para o quadro de Artesãos, e a sala dos Artesãos. Ainda sem poder além desse."
