	L.RB_GM_HERALDRY_JOB = "Cuida dos decretos, da Agenda e das convocações da guilda, e zela para que o povo compareça."
	L.RB_GM_HERALDRY_SHOWS = "O badge do Departamento de Heráldica no retrato e ao lado do nome."
